import{c as t,Q as o,j as a,m as s}from"./chunks/framework.Blq1EJLO.js";const n="/thalamus/main/runtime-request-flow.svg",p=JSON.parse('{"title":"Request flow","description":"","frontmatter":{"title":"Request flow"},"headers":[],"relativePath":"concepts/runtime/request-flow.md","filePath":"concepts/runtime/request-flow.md","lastUpdated":1795169566000}'),r={name:"concepts/runtime/request-flow.md"};function i(c,e,d,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="request-flow" tabindex="-1">Request flow <a class="header-anchor" href="#request-flow" aria-label="Permalink to &quot;Request flow&quot;">​</a></h1><p>This is how a chat completion request flows through the <a href="/thalamus/main/concepts/runtime">runtime</a>.</p><p><img src="'+n+'" alt="Request flow"></p><ol><li>Client sends <code>POST /v1/chat/completions</code> with <code>{&quot;model&quot;: &quot;zai-org/GLM-5.3&quot;}</code> to the API endpoint (<code>api.thalamus.../v1</code>).</li><li>The request reaches the API listener of the shared inference gateway. An <code>AgentgatewayPolicy</code> extracts the model name from the JSON body and sets it as the <code>X-Gateway-Base-Model-Name</code> header. Other policies, for example authentication, can apply here too (see <a href="/thalamus/main/gateway-integrations">Gateway Integrations</a>).</li><li>The per-model <code>HTTPRoute</code> matches that header and the path, and forwards to the <code>AgentgatewayBackend</code>, which references the model&#39;s <code>InferencePool</code>.</li><li>The gateway uses the <code>InferencePool</code> to discover candidate engine pods and to find the corresponding Endpoint-Picker (EPP).</li><li>The EPP scores model replicas using real-time signals (e.g. KV-cache utilization, queue depth, ...) and returns the chosen engine deployment.</li><li>vLLM generates the response and streams it back through the same path.</li></ol><p>Requests to <code>/v1/models</code> get answered directly via a model-list <code>AgentgatewayPolicy</code> that the operator keeps in sync with the <code>Ready</code> models in the namespace. Only model replicas that are ready to respond to requests are exposed to users.</p>',5)])])}const f=t(r,[["render",i]]);export{p as __pageData,f as default};
